"""R6: every generated file names the contract it was rendered from."""

from pathlib import Path

import mcphost_sdk

PKG = Path(mcphost_sdk.__file__).parent


def test_every_file_carries_the_generated_from_header() -> None:
    expected = (
        f"# generated by mcphost gen sdk python from contract {mcphost_sdk.CONTRACT_VERSION} -- do not edit"
    )
    files = [p for p in PKG.rglob("*") if p.is_file() and "__pycache__" not in p.parts]
    assert files, "no package files found"
    missing = [p.name for p in files if p.read_text().splitlines()[0] != expected]
    assert not missing, f"missing header {expected!r}: {missing}"


def test_contract_version_is_major_dot_sha12() -> None:
    major, sha12 = mcphost_sdk.CONTRACT_VERSION.split(".")
    assert major == "1" and len(sha12) == 12
    assert mcphost_sdk.CONTRACT_SHA.startswith(sha12)
